// Keep all 304 published host slots in place, including the eight original
// body controls. Size is a next-note sound control, appended with a newer
// AU ordering hint rather than inserted into either existing rank group.
for (int rank = 0; rank < 2; ++rank)
    layout.add(make(cs80::bodySizeParam(rank), 17));

reproduction.probe_source:
#include "Params.h"
#include <cstdio>
#include <string>
int main(){
 for(int i=0;i<cs80::P_numParams;++i){const auto &d=cs80::paramDef(i);std::printf("C\t%d\t%s\t%a\t%a\t%a\t%a\n",i,cs80::paramId(i).c_str(),d.min,d.max,d.def,d.skew);}
 int n=0;auto emit=[&](const std::string&id){std::printf("H\t%d\t%s\n",n++,id.c_str());};
 for(int i=0;i<cs80::P_legacyNumParams;++i)emit(cs80::paramId(i));
 for(int ch=0;ch<2;++ch)emit("hardware_source_"+std::to_string(ch+1));
 for(int bank=0;bank<4;++bank)for(int local=0;local<cs80::CP_count;++local)
  if(local!=cs80::CP_feet&&local!=cs80::CP_pan&&local!=cs80::CP_hpfOn&&local!=cs80::CP_lpfOn)emit("memory_"+std::to_string(bank+1)+"_"+cs80::kChannelDefs[local].id);
 for(int i=cs80::P_legacyNumParams;i<cs80::P_numParams;++i)emit(cs80::paramId(i));
}
